-- create-table OTTO_SHOPS
CREATE TABLE "OTTO_SHOPS" (
  "/RT/TENANT" TEXT NOT NULL,
  "SHOP_ID" TEXT NOT NULL,
  "COMPANY_ID" TEXT NOT NULL,
  "NAME" TEXT NOT NULL,
  CONSTRAINT "OTTO_SHOPS#PK" PRIMARY KEY ("/RT/TENANT", "SHOP_ID"),
  CONSTRAINT "OTTO_SHOPS#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT"),
  CONSTRAINT "OTTO_SHOPS#FK#COMPANY" FOREIGN KEY ("/RT/TENANT", "COMPANY_ID") REFERENCES "COMPANIES" ("/RT/TENANT", "COMPANY_ID"),
  CONSTRAINT "OTTO_SHOPS#CK#/RT/TENANT" CHECK ("/RT/TENANT" IS NULL OR (length("/RT/TENANT") <= 16)),
  CONSTRAINT "OTTO_SHOPS#CK#SHOP_ID" CHECK ("SHOP_ID" IS NULL OR (length("SHOP_ID") <= 12)),
  CONSTRAINT "OTTO_SHOPS#CK#COMPANY_ID" CHECK ("COMPANY_ID" IS NULL OR (length("COMPANY_ID") <= 10)),
  CONSTRAINT "OTTO_SHOPS#CK#NAME" CHECK ("NAME" IS NULL OR (length("NAME") <= 80))
) STRICT;

-- rebuild table COMPANIES: alter-type COMPANIES./TROTTO/OTTO_ID (CHAR(20) -> CHAR(32)); add-column COMPANIES./TROTTO/ACTIVE (BOOL); add-column COMPANIES./TROTTO/MAIN_SHOP (CHAR(12)); add-foreign-key COMPANIES./TROTTO/MAIN_SHOP (references OTTO_SHOPS)
CREATE TABLE "COMPANIES#NEW" (
  "/RT/TENANT" TEXT NOT NULL,
  "COMPANY_ID" TEXT NOT NULL,
  "NAME" TEXT NOT NULL,
  "COUNTRY" TEXT NOT NULL,
  "STATUS" TEXT NOT NULL DEFAULT 'ACTIVE',
  "CAPITAL" INTEGER,
  "FOUNDED_ON" TEXT,
  "/TROTTO/OTTO_ID" TEXT,
  "/TROTTO/ACTIVE" INTEGER NOT NULL DEFAULT 0,
  "/TROTTO/MAIN_SHOP" TEXT,
  CONSTRAINT "COMPANIES#PK" PRIMARY KEY ("/RT/TENANT", "COMPANY_ID"),
  CONSTRAINT "COMPANIES#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT"),
  CONSTRAINT "COMPANIES#FK#COUNTRY" FOREIGN KEY ("COUNTRY") REFERENCES "COUNTRIES" ("COUNTRY_CODE"),
  CONSTRAINT "COMPANIES#FK#/TROTTO/MAIN_SHOP" FOREIGN KEY ("/RT/TENANT", "/TROTTO/MAIN_SHOP") REFERENCES "OTTO_SHOPS" ("/RT/TENANT", "SHOP_ID"),
  CONSTRAINT "COMPANIES#CK#/RT/TENANT" CHECK ("/RT/TENANT" IS NULL OR (length("/RT/TENANT") <= 16)),
  CONSTRAINT "COMPANIES#CK#COMPANY_ID" CHECK ("COMPANY_ID" IS NULL OR (length("COMPANY_ID") <= 10)),
  CONSTRAINT "COMPANIES#CK#NAME" CHECK ("NAME" IS NULL OR (length("NAME") <= 80)),
  CONSTRAINT "COMPANIES#CK#COUNTRY" CHECK ("COUNTRY" IS NULL OR (length("COUNTRY") <= 2)),
  CONSTRAINT "COMPANIES#CK#STATUS" CHECK ("STATUS" IS NULL OR (length("STATUS") <= 10 AND "STATUS" IN ('ACTIVE', 'BLOCKED', 'CLOSED'))),
  CONSTRAINT "COMPANIES#CK#CAPITAL" CHECK ("CAPITAL" IS NULL OR ("CAPITAL" BETWEEN -999999999999999 AND 999999999999999)),
  CONSTRAINT "COMPANIES#CK#FOUNDED_ON" CHECK ("FOUNDED_ON" IS NULL OR ("FOUNDED_ON" IS date("FOUNDED_ON"))),
  CONSTRAINT "COMPANIES#CK#/TROTTO/OTTO_ID" CHECK ("/TROTTO/OTTO_ID" IS NULL OR (length("/TROTTO/OTTO_ID") <= 32)),
  CONSTRAINT "COMPANIES#CK#/TROTTO/ACTIVE" CHECK ("/TROTTO/ACTIVE" IS NULL OR ("/TROTTO/ACTIVE" IN (0, 1))),
  CONSTRAINT "COMPANIES#CK#/TROTTO/MAIN_SHOP" CHECK ("/TROTTO/MAIN_SHOP" IS NULL OR (length("/TROTTO/MAIN_SHOP") <= 12))
) STRICT;
INSERT INTO "COMPANIES#NEW" ("/RT/TENANT", "COMPANY_ID", "NAME", "COUNTRY", "STATUS", "CAPITAL", "FOUNDED_ON", "/TROTTO/OTTO_ID") SELECT "/RT/TENANT", "COMPANY_ID", "NAME", "COUNTRY", "STATUS", "CAPITAL", "FOUNDED_ON", "/TROTTO/OTTO_ID" FROM "COMPANIES";
DROP TABLE "COMPANIES";
ALTER TABLE "COMPANIES#NEW" RENAME TO "COMPANIES";

